pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    // The test contract is c's factory; provide the getter c calls.
    function protocolFeeRate() external pure returns (uint16) {
        return 0;
    }

    function setUp() public {
        c = new C(address(this), address(this), address(this));
    }

    function testFuzz_property(uint56 changeFee, uint8 decimals_, uint128 vbr, uint128 vnr, uint16 feeRate) public {
        vm.assume(decimals_ >= 4 && decimals_ <= 36);
        feeRate = uint16(bound(feeRate, 0, 5_000));

        TestToken token = new TestToken(decimals_);

        c.initialize(
            address(token),
            address(token),
            vbr,
            vnr,
            changeFee,
            feeRate,
            bytes32(0),
            false,
            false
        );

        uint256 expectedFee = uint256(changeFee) * (10 ** (uint256(decimals_) - 4));

        (uint256 feeAmount, ) = c.changeFeeQuote(1e18);

        assertTrue(feeAmount == expectedFee);
    }
}

contract TestToken {
    uint8 public immutable decimals;

    constructor(uint8 d) {
        decimals = d;
    }
}

