pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(uint56 fee1, uint56 fee2, uint128 vb, uint128 vn) public {
        // First initialization with fee1: succeeds on both versions.
        c.initialize(address(0), address(0), vb, vn, fee1, 0, bytes32(0), false, false);

        // A second initialization attempt must be a no-op: it reverts
        // (AlreadyInitialized) and must NOT alter any stored parameter,
        // in particular changeFee.
        try c.initialize(address(0), address(0), vb, vn, fee2, 0, bytes32(0), false, false) {
            // should not happen on either version
        } catch {}

        assertTrue(c.changeFee() == fee1);
    }
}
